class TagIndex:
    def __init__(self):
        self._items = {}

    def put(self, document, metadata):
        self._items[document] = metadata

    def summary(self):
        return dict(self._items)


def render_count(index):
    return f"documents={len(index.summary())}"
import unittest
from tagindex import TagIndex, render_count


class CurrentConsumer(unittest.TestCase):
    def test_count(self):
        index = TagIndex()
        index.put("a", {"tags": ["x"]})
        self.assertEqual(render_count(index), "documents=1")
